        saveForm(form) {
            const entryIndex = this.entries.findIndex((entry) => entry.key === this.currentKey);
            if (entryIndex < 0) {
                return;
            }
            const data = new FormData(form);
            this.entries[entryIndex] = normalizeEncyclopediaEntry({
                ...this.entries[entryIndex],
                monsterDrops: data.get('monsterDrops'),
                npcSources: data.get('npcSources'),
                serverSources: data.get('serverSources'),
                suitableJobs: data.get('suitableJobs'),
                owned: {
                    inventory: data.has('ownedInventory'), storage: data.has('ownedStorage'),
                    equipped: data.has('ownedEquipped'), cardAlbum: data.has('ownedCardAlbum')
                },
                notes: data.get('notes'),
                lastSeenAt: nowIso()
            });
            this.currentItem = this.entries[entryIndex];
            this.save();
            this.editing = false;
            this.renderCurrent();
            this.assistant.setStatus(`已保存“${this.entries[entryIndex].itemName}”的本服百科`);
        }

