            const description = normalizeText(item?.itemDescription || item?.description
                || (Array.isArray(info?.identifiedDescriptionName) ? info.identifiedDescriptionName.join('\n') : info?.identifiedDescriptionName || ''));
            return { database, info, itemId, description };
