        headgearSlot(item) {
            const { description } = this.itemDatabaseInfo(item);
            const location = Number(this.assistant.readItemEquipmentLocation(item)) || 0;
            const loc = this.assistant.getEquipmentLocationConstants();
            if ((location & (Number(loc.HEAD_TOP) || 256)) || (location & (Number(loc.COSTUME_HEAD_TOP) || 1024)) || /头上|頭上|上段/u.test(description)) return 'accessory2';
            if ((location & (Number(loc.HEAD_MID) || 512)) || (location & (Number(loc.COSTUME_HEAD_MID) || 2048)) || /头中|頭中|中段/u.test(description)) return 'accessory3';
            return 'accessory';
        }

