        headgearSpriteFrame(spr) {
            if (!Array.isArray(spr?.frames)) return null;
            const palette = spr.palette;
            let best = null;
            for (let index = 0; index < spr.frames.length; index++) {
                const frame = spr.frames[index];
                const width = Number(frame?.width), height = Number(frame?.height);
                if (!(width > 0 && height > 0) || !frame.data) continue;
                const pixels = new Uint8ClampedArray(width * height * 4);
                const bounds = { left: width, right: -1, top: height, bottom: -1 };
                let visible = 0;
                for (let pixel = 0; pixel < width * height; pixel++) {
                    const dest = pixel * 4;
                    if (Number(frame.type) === 1) {
                        pixels[dest] = Number(frame.data[dest] || 0);
                        pixels[dest + 1] = Number(frame.data[dest + 1] || 0);
                        pixels[dest + 2] = Number(frame.data[dest + 2] || 0);
                        pixels[dest + 3] = Number(frame.data[dest + 3] || 0);
                    } else if (palette) {
                        const color = Number(frame.data[pixel] || 0);
                        const source = color * 4;
                        pixels[dest] = Number(palette[source] || 0);
                        pixels[dest + 1] = Number(palette[source + 1] || 0);
                        pixels[dest + 2] = Number(palette[source + 2] || 0);
                        pixels[dest + 3] = color ? 255 : 0;
                    }
                    if (!pixels[dest + 3]) continue;
                    visible++;
                    const x = pixel % width, y = Math.floor(pixel / width);
                    bounds.left = Math.min(bounds.left, x); bounds.right = Math.max(bounds.right, x);
                    bounds.top = Math.min(bounds.top, y); bounds.bottom = Math.max(bounds.bottom, y);
                }
                if (!visible) continue;
                const area = (bounds.right - bounds.left + 1) * (bounds.bottom - bounds.top + 1);
                const score = visible + area / 100000;
                if (!best || score > best.score) best = { frameIndex: index, width, height, pixels, bounds, score };
            }
            return best;
        }

        drawFloatingHeadgearFrame(canvas, sprite) {
            const context = canvas?.getContext?.('2d');
            const document = globalScope.document || canvas?.ownerDocument;
            if (!context || !document?.createElement || !sprite) return false;
            const frameCanvas = document.createElement('canvas');
            frameCanvas.width = sprite.width; frameCanvas.height = sprite.height;
            const frameContext = frameCanvas.getContext('2d');
            if (!frameContext?.createImageData) return false;
            const imageData = frameContext.createImageData(sprite.width, sprite.height);
            imageData.data.set(sprite.pixels);
            frameContext.putImageData(imageData, 0, 0);
            const cropWidth = sprite.bounds.right - sprite.bounds.left + 1;
            const cropHeight = sprite.bounds.bottom - sprite.bounds.top + 1;
            const scale = Math.min(150 / cropWidth, 98 / cropHeight);
            const drawWidth = Math.max(1, Math.round(cropWidth * scale));
            const drawHeight = Math.max(1, Math.round(cropHeight * scale));
            context.imageSmoothingEnabled = false;
            context.drawImage(frameCanvas, sprite.bounds.left, sprite.bounds.top, cropWidth, cropHeight,
                Math.round((canvas.width - drawWidth) / 2), 2, drawWidth, drawHeight);
            return true;
        }

        drawFloatingItemIcon(canvas, url, onload, onerror) {
            const context = canvas?.getContext?.('2d');
            const ImageClass = globalScope.Image || globalScope.document?.defaultView?.Image;
            if (!context || !ImageClass || !url) { onerror?.(); return; }
            const icon = new ImageClass();
            icon.onload = () => {
                const width = Number(icon.naturalWidth || icon.width), height = Number(icon.naturalHeight || icon.height);
                if (!(width > 0 && height > 0)) { onerror?.(); return; }
                const scale = Math.min(116 / width, 98 / height);
                const drawWidth = Math.max(1, Math.round(width * scale));
                const drawHeight = Math.max(1, Math.round(height * scale));
                context.imageSmoothingEnabled = false;
                context.drawImage(icon, Math.round((canvas.width - drawWidth) / 2), 2, drawWidth, drawHeight);
                onload?.();
            };
            icon.onerror = () => onerror?.();
            icon.src = url;
        }

