    function readPartyJobId(source) {
        return [source?.class_, source?.class, source?.Class, source?.job, source?.Job,
            source?.jobId, source?.jobID, source?.classId, source?.classID, source?._job]
            .map(Number).find((value) => Number.isFinite(value) && value > 0) || 0;
    }

    function featureHash(value, salt = '') {
        let hash = 0x811c9dc5;
        for (const char of `${salt}:${value ?? ''}`) {
            hash ^= char.charCodeAt(0);
            hash = Math.imul(hash, 0x01000193);
        }
        return (hash >>> 0).toString(36);
    }

    function installFeatureHook(target, method, listener) {
        if (!target || typeof target[method] !== 'function') return false;
        let wrapper = target[method];
        if (!wrapper.__lroFeatureHook) {
            const original = wrapper;
            const listeners = new Set();
            wrapper = function lroFeatureHook(...args) {
                const result = original.apply(this, args);
                for (const callback of [...listeners]) {
                    try { callback(args, result, this); } catch (_error) { /* keep native UI working */ }
                }
                return result;
            };
            Object.defineProperties(wrapper, {
                __lroFeatureHook: { value: true },
                __lroFeatureListeners: { value: listeners }
            });
            target[method] = wrapper;
        }
        target[method].__lroFeatureListeners.add(listener);
        return true;
    }

