            const explicitName = normalizeText(member.name ?? member.characterName);
            const oldName = /^队员\s+\d+$/.test(old.name || '') ? '' : normalizeText(old.name);
            const sessionName = normalizeText(session.Entity?.display?.name ?? session.Character?.name);
            const wantedName = explicitName || oldName;
            const isSelf = [session.AID, session.GID, session.Entity?.GID, session.Character?.GID].some((id) => normalizeText(id) === aid)
                || Boolean(sessionName && wantedName === sessionName);
            let entity = isSelf ? (session.Entity || session.Character) : null;
            entity ||= this.findMemberEntity(aid, wantedName);
            const hp = Math.max(0, Number(member.hp ?? member.life?.hp ?? old.hp ?? entity?.life?.hp ?? 0) || 0);
            const maxhp = Math.max(0, Number(member.maxhp ?? member.maxHp ?? member.life?.maxhp ?? member.life?.maxHp ?? member.life?.hp_max ?? old.maxhp ?? entity?.life?.maxhp ?? entity?.life?.maxHp ?? entity?.life?.hp_max ?? 0) || 0);
            const entityName = normalizeText(entity?.display?.name ?? entity?.name);
