                const placeType = Number(selection.TYPE?.PLACE ?? 2);
                const skill = selected?.skill;
                const skillId = Number(skill?.SKID ?? skill?.skillID ?? skill?.id ?? 0);
                const skillName = normalizeText(this.assistant.getAmdModule('DB/Skills/SkillInfo')?.[skillId]?.SkillName ?? skill?.name);
                const supportedGroundSkill = skillId === 12 || skillId === 25
