                    title: '隐藏自己的时装', positionKey: 'costumeSettings', width: 280,
                    content: `.help{margin-bottom:7px;color:#555;line-height:1.5}.master{display:flex;align-items:center;gap:5px;margin-bottom:6px;padding:6px;border:1px solid #9fb4ca;background:#edf5ff;font-weight:700}.slots{display:grid;grid-template-columns:repeat(3,1fr);gap:5px}.slots label{display:flex;align-items:center;gap:4px;padding:6px;border:1px solid #c4c4c4;background:#fff}`
