    function outfitItemKey(item) {
        // 客户端库存 index 会在重登后变化，不能作为持久标识；不按名称选装备。
        const cards = [1, 2, 3, 4].map((n) => Number(item.slot?.['card' + n] || 0));
        const options = Array.from({ length: 5 }, (_, n) => [
            Number(item.options?.['Index' + n] || 0), Number(item.options?.['Value' + n] || 0), Number(item.options?.['Param' + n] || 0)
        ]);
        return JSON.stringify([Number(item.ITID), Number(item.RefiningLevel || 0), Number(item.enchantgrade || 0), cards, options, Number(item.HireExpireDate || 0)]);
    }

    function outfitUid(item) {
        // 当前 LastRO 库存封包没有永久实例号；未来客户端有明确实例号时才使用。
        const value = item.uniqueId ?? item.uniqueID ?? item.UniqueID;
        return value != null && String(value) !== '0' ? String(value) : '';
    }

    function outfitMatches(saved, item) {
        return saved.key === outfitItemKey(item) && (!saved.uid || saved.uid === outfitUid(item));
    }

    function outfitStateSignature(items) {
        return JSON.stringify(items.map(({ item, location }) => [Number(item.index), location, outfitItemKey(item), outfitUid(item)]).sort((a, b) => a[0] - b[0]));
    }

